"""Make array of dictionaries as a list.

    Args:
        points: array of dictionaries - [{'x': x_coord, 'y': y_coord}].

    Returns:
        list: points as a list.
    """
def points_to_list(points: Any) -> object {
    points_list = [];
    for point in points {
        points_list.append([int(point['x']), int(point['y'])]);
    }
    return points_list;
}

"""
    Merges two lists alternately.

    E.g.:

    first = [1, 2]
    second = ["A", "B"]

    result = [1, "A", 2, "B"]
    """
def merge_lists(first: Any, second: Any) -> object {
    return [item for pair in zip(first, second) for item in pair];
}

""" If `str_or_list` is a list will return it as it is. If it is a str, will return a
    list with the str inside.

    Parameters
    ----------
    str_or_list: str or list

    Returns
    -------
    list
    """
def _check_list(str_or_list: Any) -> object {
    if (str_or_list is None) {
        return None;
    }
    if isinstance(str_or_list, `list) {
        return str_or_list;
    }
    if isinstance(str_or_list, str) {
        return [str_or_list];
    }
    raise ValueError(
        'Expected a `str` or a `list`, ' 'got {}.'.format(`type(str_or_list))
    );
}

""" Utility method to convert a file size in bytes to a human-readable format

    Args:
        num    (int): Number of bytes
        suffix (str): Suffix for 'bytes'

    Returns:
        str: The formatted file size as a string, eg. ``1.21 GB``
    """
def sizeof(num: Any, suffix: Any = 'B') -> object {
    for unit in ['', 'K', 'M', 'G', 'T', 'P', 'E', 'Z'] {
        if (abs(num) < 1024.0) {
            return ("%3.1f %s%s" % (num, unit, suffix));
        }
        num /= 1024.0;
    }
    return ("%.1f %s%s" % (num, 'Y', suffix));
}

